import torch

class CubeFunction(torch.autograd.Function):
    @staticmethod
    def forward(ctx, x):
        ctx.save_for_backward(x)
        return x ** 3

    @staticmethod
    def backward(ctx, grad_output):
        (x,) = ctx.saved_tensors
        return grad_output * 3 * (x ** 2)

x = torch.tensor([2.0, 3.0], requires_grad=True)
# Execute custom function via .apply()
y = CubeFunction.apply(x)
loss = y.sum()
loss.backward()

print(f"Custom backward gradient: {x.grad}")

import torch

class DoubleFunction(torch.autograd.Function):
    @staticmethod
    def forward(ctx, x):
        return x * 2.0

    @staticmethod
    def backward(ctx, grad_output):
        return grad_output * 2.0

# Inputs MUST use double precision (float64) for finite-difference accuracy
inputs = (torch.randn(2, 2, dtype=torch.float64, requires_grad=True),)
test_passed = torch.autograd.gradcheck(DoubleFunction.apply, inputs, eps=1e-6, atol=1e-4)

print(f"Gradcheck result: {test_passed}")
